records = []
for year, rows in ROWS.items():
    assert len(rows) == 20 and len(KEYS[year]) == 20
    positions = {}
    for spread, side, items in CROPS[year]:
        source = Image.open(ROOT / f'tmp/sources/render/{year}-{spread}-{side}.png').convert('RGB')
        for number, top, bottom in items:
            crop = source.crop((80, top, 1120, bottom))
            if year == 2023 and number == 16:
                ImageDraw.Draw(crop).rectangle((0,0,740,54), fill='white')
            if year == 2023 and number == 15:
                ImageDraw.Draw(crop).rectangle((745,165,1040,crop.height), fill='white')
            if year == 2024 and number == 2:
                ImageDraw.Draw(crop).rectangle((0,180,100,crop.height), fill='white')
            if year == 2026 and number == 17:
                ImageDraw.Draw(crop).rectangle((0,0,900,35), fill='white')
            dest = OUT / f'{year}-{number:02}.webp'
            crop.save(dest, 'WEBP', lossless=True, method=6)
            positions[number] = {'spread': spread, 'side': side, 'crop': [80,top,1120,bottom]}
    for index, (topic, text, options) in enumerate(rows):
        number = index + 1
        records.append({
            'id': f'original-{year}-{number:02}', 'number': number, 'topic': topic,
            'text': text, 'options': options, 'correct': KEYS[year][index],
            'points': 3 if number <= 8 else 4 if number <= 16 else 5,
            'setId': f'original-{year}',
            'image': {'src': f'assets/tasks/originals/{year}-{number:02}.webp', 'alt': text, 'kind': 'question'},
            'source': {'kind': 'original', 'year': year, 'contest': 'Смарт Кенгуру', 'grade': '3–4',
                       'file': FILES[year], 'url': 'https://mathkang.ru/rar', 'answerKeyUrl': KEY_URLS[year],
                       'answerVerified': True, **positions[number]},
        })
    source_hash = hashlib.sha256((ROOT / 'исходники' / FILES[year]).read_bytes()).hexdigest()
    (ROOT / 'data' / f'source-{year}.json').write_text(json.dumps({
        'year': year, 'file': FILES[year], 'sha256': source_hash, 'tasks': 20, 'answerKeyUrl': KEY_URLS[year],
        'answerIndexes': KEYS[year], 'review': 'Source crops and official answer key visually checked'
    }, ensure_ascii=False, indent=2), encoding='utf-8')
(ROOT / 'data/originals.json').write_text(json.dumps(records, ensure_ascii=False, indent=2), encoding='utf-8')
# Contact sheets help verify that all 20 excerpts are complete and correctly numbered.
for year in ROWS:
    sheet = Image.new('RGB', (1200, 1250), '#dde8ee')
    draw = ImageDraw.Draw(sheet)
    for n in range(1,21):
        x = (n-1) % 4 * 300
        y = (n-1) // 4 * 250
        preview = Image.open(OUT / f'{year}-{n:02}.webp').convert('RGB')
        preview.thumbnail((284,216))
        draw.text((x+8,y+5), f'{year} / {n}', fill='#304d59')
        sheet.paste(preview, (x+8,y+27))
    sheet.save(ROOT / f'tmp/sources/render/contact-{year}.jpg', quality=94)
print(f'Imported {len(records)} original tasks with source images and official keys.')
